import{H as e,V as t,j as n,tt as r}from"./chunks/framework.CtsVvn0U.js";var i=JSON.parse(`{"title":"What is MCP Kit?","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/what-is-mcp-kit.md","filePath":"en/guide/what-is-mcp-kit.md"}`),a={name:`guide/what-is-mcp-kit.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /mcp-kit/guide/what-is-mcp-kit.md for this page in Markdown format</div><h1 id="what-is-mcp-kit" tabindex="-1">What is MCP Kit? <a class="header-anchor" href="#what-is-mcp-kit" aria-label="Permalink to “What is MCP Kit?”">​</a></h1><p>MCP Kit is an interactive scaffolding CLI for Model Context Protocol (MCP) applications. It generates ready-to-develop servers and clients whose source code, scripts, tests, and documentation match the choices made in the setup wizard.</p><h2 id="what-it-generates" tabindex="-1">What it generates <a class="header-anchor" href="#what-it-generates" aria-label="Permalink to “What it generates”">​</a></h2><p>MCP Kit supports both sides of an MCP integration:</p><ul><li><strong>MCP Server</strong> projects register tools, resources, and prompts and expose them over STDIO, Streamable HTTP, or both.</li><li><strong>MCP Client</strong> projects include connection helpers and a complete example that discovers and uses those server capabilities.</li></ul><p>Every project can use TypeScript or JavaScript. The generated code uses modern ES modules and includes build and local development scripts.</p><h2 id="a-working-example-not-an-empty-shell" tabindex="-1">A working example, not an empty shell <a class="header-anchor" href="#a-working-example-not-an-empty-shell" aria-label="Permalink to “A working example, not an empty shell”">​</a></h2><p>The paired server and client templates demonstrate one end-to-end knowledge-base workflow:</p><ol><li>The client calls the <code>search_documents</code> tool.</li><li>The tool returns structured matches and stable <code>kb://documents/{documentId}</code> resource URIs.</li><li>The client reads the selected Markdown resource.</li><li>The client gets the <code>review_document</code> prompt with that resource attached.</li></ol><p>The example is deterministic and does not depend on an external database or API, so it can be used as a runnable reference before you replace it with your own domain logic.</p><h2 id="transports" tabindex="-1">Transports <a class="header-anchor" href="#transports" aria-label="Permalink to “Transports”">​</a></h2><ul><li><strong>STDIO</strong> is intended for local, process-based integrations. The generated server communicates through standard input and output.</li><li><strong>Streamable HTTP</strong> exposes an MCP endpoint at <code>/mcp</code>; the generated development server listens on port <code>8401</code> by default.</li></ul><p>Selecting both transports keeps their implementations separate and adds a script for each one.</p><h2 id="standard-and-custom-setups" tabindex="-1">Standard and custom setups <a class="header-anchor" href="#standard-and-custom-setups" aria-label="Permalink to “Standard and custom setups”">​</a></h2><p>The <strong>Standard</strong> setup enables the recommended engineering stack:</p><ul><li>GitHub Actions</li><li>Vitest</li><li>MCP Inspector for server projects</li><li>ESLint, Prettier, and lint-staged</li><li>Commitlint</li><li>changelog tooling</li></ul><p>The <strong>Custom</strong> setup lets you select any combination of those plugins, including none of them.</p><h2 id="next-step" tabindex="-1">Next step <a class="header-anchor" href="#next-step" aria-label="Permalink to “Next step”">​</a></h2><p>Continue to <a href="./getting-started.html">Getting Started</a> to generate and run a project.</p>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};